    .main-nav{display:flex;align-items:center;gap:6px;margin-left:auto}.main-nav a{padding:10px 12px;border-radius:12px;color:rgba(255,255,255,.68);font-size:13px;font-weight:600}.main-nav a:hover{background:rgba(255,255,255,.07);color:#fff}.nav-actions{display:flex;align-items:center;gap:8px}.ticket-cta{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 16px;border-radius:13px;background:var(--acid);color:var(--pine-950);font-size:13px;font-weight:800;white-space:nowrap}.menu-btn{display:none;place-items:center;width:40px;height:40px;border:0;border-radius:13px;background:rgba(255,255,255,.07);color:#fff}
