    .hero-visual{position:relative;display:grid;place-items:center;min-height:640px;padding:48px}.hero-visual:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,var(--pine-900),rgba(9,37,29,.24) 34%,rgba(9,37,29,.08)),url("https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1200&q=85") center/cover;opacity:.83}.gift-stage{position:relative;z-index:4;width:min(470px,100%);perspective:1200px}.gift-card{position:relative;overflow:hidden;aspect-ratio:1.55;border-radius:30px;background:linear-gradient(145deg,#173e32,#0a261e 70%);box-shadow:0 42px 110px -42px rgba(0,0,0,.88);transform:rotate(4deg);transition:transform .45s cubic-bezier(.2,.8,.2,1)}.gift-stage:hover .gift-card{transform:rotate(1.5deg) translateY(-5px)}.gift-card:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 78% 20%,rgba(223,252,98,.22),transparent 24%),radial-gradient(circle at 18% 80%,rgba(242,123,74,.16),transparent 24%),url("data:image/svg+xml,%3Csvg width='560' height='360' viewBox='0 0 560 360' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' stroke='%23fff' stroke-opacity='.08'%3E%3Cpath d='M-20 230c86-110 189-115 261-31 68 79 132 73 210 4 70-61 128-48 170 4'/%3E%3Cpath d='M-28 263c93-109 200-108 276-25 70 76 137 67 213-1 67-59 126-47 165-9'/%3E%3Cpath d='M-35 297c103-108 211-98 289-19 73 72 141 59 215-6 64-57 122-47 160-18'/%3E%3C/g%3E%3C/svg%3E") center/cover}.gift-inner{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:space-between;padding:32px;color:#fff}.gift-brand{display:flex;align-items:center;justify-content:space-between}.gift-brand strong{font-family:"Fraunces",serif;font-size:23px;font-weight:600}.gift-brand span{font-size:9px;font-weight:800;letter-spacing:.2em;text-transform:uppercase;color:rgba(255,255,255,.48)}.gift-main small{display:block;color:var(--acid);font-size:9px;font-weight:900;letter-spacing:.17em;text-transform:uppercase}.gift-main h2{max-width:340p