    .section{padding:86px 0}.section-head{display:flex;align-items:end;justify-content:space-between;gap:32px;margin-bottom:30px}.section-head h2{max-width:760px;margin:0;font-family:"Fraunces",serif;font-size:clamp(36px,4.4vw,64px);font-weight:600;letter-spacing:-.055em;line-height:.96}.section-head h2 em{color:var(--pine-700);font-style:italic}.section-head p{max-width:470px;margin:0;color:var(--muted);font-size:14px;line-height:1.7}
    .builder-wrap{display:grid;grid-template-columns:minmax(0,1fr) 420px;gap:24px;align-items:start}.builder{padding:28px;border:1px solid var(--line);border-radius:32px;background:rgba(255,253,246,.86);box-shadow:var(--card-shadow);backdrop-filter:blur(18px)}.steps{display:flex;gap:8px;overflow-x:auto;padding-bottom:4px;scrollbar-width:none}.steps::-webkit-scrollbar{display:none}.step-pill{display:flex;align-items:center;gap:8px;flex:0 0 auto;padding:9px 12px;border:1px solid var(--line);border-radius:999px;background:var(--cream);color:rgba(22,35,30,.52);font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.1em}.step-pill b{display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:var(--oat);font-size:10px}.step-pill.active{border-color:rgba(9,37,29,.3);background:var(--pine-900);color:#fff}.step-pill.active b{background:var(--acid);color:var(--pine-950)}.builder-panel{margin-top:28px}.panel-kicker{margin:0 0 10px;color:var(--pine-700);font-size:10px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.builder-panel h3{margin:0;font-family:"Fraunces",serif;font-size:32px;font-weight:600;letter-spacing:-.04em}.builder-panel>p{max-width:690px;margin:9px 0 0;color:var(--muted);font-size:13px;line-height:1.65}.option-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:22px}.option{position:relative;overflow:hidden;min-height:150px;padding:18px;border:1px solid var(--line);border-radius:22px;background:var(--cream);text-align:left;transition:.22s ease}.option:hover{transform:translateY(-3px);box-shadow:var(--card-shadow)}.option.active{border-color:var(--pine-900);box-shadow:0 0 0 2px var(--pine-900) inset}.option.active:after{content:"✓";position:absolute;right:12px;top:12px;display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:var(--acid);color:var(--pine-950);font-weight:900}.option-icon{display:grid;place-items:center;width:40px;height:40px;border-radius:14px;background:var(--oat);color:var(--pine-900)}.option strong{display:block;margin-top:16px;font-size:13px}.option span{display:block;margin-top:6px;color:var(--muted);font-size:11px;line-height:1.5}.amount-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:20px}.amount{min-height:82px;border:1px solid var(--line);border-radius:18px;background:var(--cream);color:var(--pine-900);font-family:"Fraunces",serif;font-size:24px;font-weight:600}.amount.active{border-color:var(--pine-900);background:var(--pine-900);color:var(--acid)}.custom-amount{display:flex;align-items:center;gap:10px;margin-top:12px;padding:12px 14px;border:1px solid var(--line);border-radius:18px;background:var(--cream)}.custom-amount input{width:100%;border:0;background:transparent;color:var(--ink);font-size:15px;outline:none}.field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:22px}.field{display:grid;gap:7px}.field.full{grid-column:1/-1}.field label{font-size:10px;font-weight:900;letter-spacing:.1em;text-transform:uppercase;color:rgba(22,35,30,.58)}.control{width:100%;min-height:48px;padding:0 14px;border:1px solid var(--line);border-radius:15px;background:var(--cream);color:var(--ink);outline:none}.control:focus{border-color:rgba(9,37,29,.42);box-shadow:0 0 0 4px rgba(9,37,29,.06)}textarea.control{min-height:120px;padding-top:13px;resize:vertical}.themes{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}.theme-btn{display:flex;align-items:center;gap:8px;padding:9px 12px;border:1px solid var(--line);border-radius:999px;background:var(--cream);font-size:11px;font-weight:800}.theme-btn i{width:16px;height:16px;border-radius:50%}.theme-btn.active{border-color:var(--pine-900);background:var(--pine-900);color:#fff}.delivery-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:20px}.delivery-option{padding:17px;border:1px solid var(--line);border-radius:20px;background:var(--cream);text-align:left}.delivery-option.active{border-color:var(--pine-900);box-shadow:0 0 0 2px var(--pine-900) inset}.delivery-option strong{display:block;font-size:12px}.delivery-option span{display:block;margin-top:5px;color:var(--muted);font-size:10px;line-height:1.5}.builder-actions{display:flex;justify-content:space-between;gap:12px;margin-top:26px;padding-top:20px;border-top:1px solid var(--line)}
    .summary{position:sticky;top:96px;padding:22px;border:1px solid var(--line);border-radius:30px;background:var(--pine-900);color:#fff;box-shadow:var(--shadow)}.summary-preview{position:relative;overflow:hidden;aspect-ratio:1.55;border-radius:22px;background:linear-gradient(145deg,#174235,#0b281f)}.summary-preview:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 82% 20%,rgba(223,252,98,.2),transparent 26%),url("data:image/svg+xml,%3Csvg width='500' height='320' viewBox='0 0 500 320' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' stroke='%23fff' stroke-opacity='.08'%3E%3Cpath d='M-20 210c70-94 160-103 226-35 67 68 127 65 198 7 59-48 104-40 138-12'/%3E%3Cpath d='M-28 244c80-93 172-97 239-29 66 67 130 59 198 2 57-47 101-42 136-19'/%3E%3C/g%3E%3C/svg%3E") center/cover}.summary-preview>div{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:space-between;padding:20px}.summary-preview small{color:var(--acid);font-size:8px;font-weight:900;letter-spacing:.16em;text-transform:uppercase}.summary-preview h4{margin:6px 0 0;font-family:"Fraunces",serif;font-size:26px;font-weight:600;letter-spacing:-.045em;line-height:1}.summary-preview p{margin:8px 0 0;color:rgba(255,255,255,.56);font-size:9px;line-height:1.4}.summary-value{font-family:"Fraunces",serif;font-size:28px;color:var(--acid)}.summary-list{display:grid;gap:11px;margin-top:20px;padding:18px 0;border-top:1px solid rgba(255,255,255,.1);border-bottom:1px solid rgba(255,255,255,.1)}.summary-line{display:flex;justify-content:space-between;gap:16px;font-size:11px}.summary-line span{color:rgba(255,255,255,.52)}.summary-line strong{text-align:right}.summary-total{display:flex;align-items:end;justify-content:space-between;margin-top:18px}.summary-total span{font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:rgba(255,255,255,.5)}.summary-total strong{font-family:"Fraunces",serif;font-size:34px;color:var(--acid)}.summary .btn{width:100%;margin-top:18px}.summary-note{display:flex;align-items:flex-start;gap:9px;margin-top:14px;color:rgba(255,255,255,.5);font-size:9px;line-height:1.5}.summary-note svg{width:15px;height:15px;flex:0 0 auto;color:var(--acid)}
    .story-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:24px}.story-card{position:relative;overflow:hidden;min-height:480px;border-radius:32px;background:var(--pine-900);color:#fff;box-shadow:var(--card-shadow)}.story-card img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.7}.story-card:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(6,26,21,.06),rgba(6,26,21,.88))}.story-copy{position:absolute;z-index:3;left:0;right:0;bottom:0;padding:32px}.story-copy small{color:var(--acid);font-size:9px;font-weight:900;letter-spacing:.15em;text-transform:uppercase}.story-copy h3{max-width:520px;margin:10px 0 12px;font-family:"Fraunces",serif;font-size:38px;font-weight:600;letter-spacing:-.05em;line-height:1}.story-copy p{max-width:580px;margin:0;color:rgba(255,255,255,.64);font-size:12px;line-height:1.65}.benefit-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.benefit{padding:22px;border:1px solid var(--line);border-radius:25px;background:rgba(255,253,246,.84);box-shadow:var(--card-shadow)}.benefit-icon{display:grid;place-items:center;width:42px;height:42px;border-radius:15px;background:var(--pine-900);color:var(--acid)}.benefit strong{display:block;margin-top:18px;font-size:13px}.benefit p{margin:7px 0 0;color:var(--muted);font-size:11px;line-height:1.55}
    .faq-grid{display:grid;grid-template-columns:.75fr 1.25fr;gap:28px;align-items:start}.faq-intro{position:sticky;top:110px}.faq-intro h2{margin:0;font-family:"Fraunces",serif;font-size:44px;font-weight:600;letter-spacing:-.055em;line-height:.98}.faq-intro p{margin:14px 0 0;color:var(--muted);font-size:13px;line-height:1.7}.faq-list{display:grid;gap:10px}.faq-item{border:1px solid var(--line);border-radius:20px;background:rgba(255,253,246,.8);overflow:hidden}.faq-q{display:flex;align-items:center;justify-content:space-between;gap:18px;width:100%;padding:18px 20px;border:0;background:transparent;text-align:left;font-size:12px;font-weight:800}.faq-q svg{width:18px;height:18px;transition:.2s ease}.faq-item.open .faq-q svg{transform:rotate(45deg)}.faq-a{max-height:0;overflow:hidden;transition:max-height .3s ease}.faq-a p{margin:0;padding:0 20px 18px;color:var(--muted);font-size:11px;line-height:1.65}
