            <div class="field-grid"><div class="field full" x-show="delivery!=='self'" x-cloak><label for="recipientEmail">Email destinatar</label><input id="recipientEmail" class="control" type="email" placeholder="mara@email.ro" x-model="recipientEmail"></div><div class="field" x-show="delivery==='scheduled'" x-cloak><label for="deliveryDate">Data livrării</label><input id="deliveryDate" class="control" type="date" x-model="deliveryDate"></div><div class="field" x-show="delivery==='scheduled'" x-cloak><label for="deliveryTime">Ora</label><input id="deliveryTime" class="control" type="time" x-model="deliveryTime"></div><div class="field full" x-show="delivery==='self'" x-cloak><label for="buyerEmail">Emailul tău</label><input id="buyerEmail" class="control" type="email" placeholder="andrei@email.ro" x-model="buyerEmail"></div></div>
          </section>
          <div class="builder-actions"><button class="btn btn-soft" type="button" @click="prevStep()" :disabled="step===1" :style="step===1?'opacity:.4;cursor:not-allowed':''">Înapoi</button><button class="btn btn-dark" type="button" @click="nextStep()" x-text="step<4?'Continuă':'Verifică voucherul'"></button></div>
