<script>
function giftCardPage(){return{
  menuOpen:false,step:1,type:'value',amount:250,customAmount:'',quantity:1,sender:'',recipient:'',occasion:'Zi de naștere',message:'',theme:'forest',experience:'Canopy Run',membership:'Wild Circle',delivery:'now',recipientEmail:'',buyerEmail:'',deliveryDate:'',deliveryTime:'10:00',openFaq:null,toast:'',toastVisible:false,
  defaultMessage:'O zi de aer curat, curaj și libertate, aleasă exact când e momentul potrivit.',
  faqs:[
    {q:'Voucherul poate fi folosit pentru orice experiență?',a:'Voucherul valoric poate fi folosit pentru orice produs eligibil disponibil online. Voucherele legate de experiență sau membership se folosesc pentru produsul ales ori pentru o variantă echivalentă, conform condițiilor afișate.'},
    {q:'Ce se întâmplă dacă rezervarea costă mai mult?',a:'Destinatarul introduce codul voucherului în checkout, iar diferența poate fi achitată cu cardul.'},
    {q:'Pot programa livrarea pentru o anumită zi?',a:'Da. Alegi data și ora, iar emailul va fi trimis automat atunci. Livrarea programată poate fi modificată până la momentul procesării.'},
    {q:'Voucherul poate fi rambursat?',a:'Voucherele neutilizate pot fi anulate de cumpărător în condițiile politicii comerciale aplicabile. După utilizarea parțială sau integrală, nu mai pot fi rambursate.'},
    {q:'Pot tipări voucherul?',a:'Da. Cumpărătorul și destinatarul primesc un PDF optimizat pentru tipărire, alături de versiunea digitală.'}
  ],
  init(){this.$watch('type',()=>{if(this.type==='experience')this.amount=this.experiencePrice;if(this.type==='membership')this.amount=this.membershipPrice});this.$watch('experience',()=>{if(this.type==='experience')this.amount=this.experiencePrice});this.$watch('membership',()=>{if(this.type==='membership')this.amount=this.membershipPrice});},
  get experiencePrice(){return {'Canopy Run':189,'Forest Quest':149,'Family Trail':249}[this.experience]||189},
  get membershipPrice(){return {'Trail Key':390,'Wild Circle':690,'Summit Society':990}[this.membership]||690},
  get unitValue(){if(this.type==='experience')return this.experiencePrice;if(this.type==='membership')return this.membershipPrice;return Number(this.amount)||250},
  get total(){return this.unitValue*this.quantity},
  get displayValue(){return this.type==='experience'?this.experience:this.type==='membership'?this.membership:this.unitValue+' RON'},
  get typeLabel(){return this.type==='value'?'Voucher valoric':this.type==='experience'?this.experience:this.membership},
  get typeKicker(){return this.type==='value'?'Voucher valoric':this.type==='experience'?'Experiență cadou':'Membership cadou'},
  get deliveryLabel(){if(this.delivery==='self')return 'PDF trimis cumpărătorului';if(this.delivery==='scheduled')return this.deliveryDate?'Livrare '+this.deliveryDate:'Livrare programată';return 'Livrare instant pe email'},
  get cardStyle(){const m={forest:'linear-gradient(145deg,#173e32,#0a261e 70%)',sunset:'linear-gradient(145deg,#9c4c33,#3b211b 74%)',mist:'linear-gradient(145deg,#5d9992,#173934 74%)'};return 'background:'+m[this.theme]},
  syncCustomAmount(){const v=Math.max(100,Math.min(2000,Number(this.customAmount)||0));if(v)this.amount=v},
  goTo(n){this.step=n;document.getElementById('configure')?.scrollIntoView({behavior:'smooth',block:'start'})},
  nextStep(){if(this.step<4){this.step++;return}this.showToast('Voucherul este gata de verificare. Poți continua către coș.')},prevStep(){if(this.step>1)this.step--},
  toggleFaq(i){this.openFaq=this.openFaq===i?null:i},scrollPreview(){document.getElementById('preview')?.scrollIntoView({behavior:'smooth',block:'center'})},
  async addToCart(){if(this.type==='value'&&(this.unitValue<100||this.unitValue>2000)){this.showToast('Valoarea trebuie să fie între 100 și 2.000 RON.');return}if(this.delivery!=='self'&&!this.recipientEmail){this.step=4;this.showToast('Completează emailul destinatarului înainte de a continua.');return}
    // Emiterea voucherului cadou necesită autentificare (endpoint tenant-client acc-gift-purchase).
    let auth=null;try{auth=JSON.parse(localStorage.getItem('nordvale_auth')||'null')}catch(e){}
    if(!auth||!auth.token){this.showToast('Autentifică-te pentru a emite voucherul.');setTimeout(()=>{window.location.href='/autentificare?next=/card-cadou'},900);return}
    this.showToast('Se emite voucherul...');
    try{
      const res=await fetch('/api/proxy.php?action=acc-gift-purchase',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+auth.token},body:JSON.stringify({amount:this.unitValue,recipient_name:this.recipient||'',message:this.message||''})});
      const data=await res.json().catch(()=>null);
      if(res.ok&&data&&data.success&&data.data){
        const p=new URLSearchParams({code:data.data.code||'',amount:String(data.data.balance!=null?data.data.balance:this.unitValue),to:this.recipient||'',msg:this.message||'',email:this.recipientEmail||'',from:(auth.user&&auth.user.email)?auth.user.email:''});
        window.location.href='/card-cadou-confirmare?'+p.toString();return;
      }
      this.showToast((data&&data.error)?data.error:'Voucherul nu a putut fi emis. Încearcă din nou.');
    }catch(e){this.showToast('Conexiune eșuată. Încearcă din nou.');}
  },
  showToast(msg){this.toast=msg;this.toastVisible=true;clearTimeout(this._t);this._t=setTimeout(()=>this.toastVisible=false,2600)}
}}
</script>
</body>
</html>
